import * as THREE from 'three';
import {PRODUCE_BY_ID} from './layout.js';
import {harvestPose,produceGeometries} from './view.js';
const smooth=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)};
const FRUIT_COLORS={strawberry:'#d95662',tomato:'#df6448',pumpkin:'#e6a04b',leafy:'#82ad62',peach:'#eba9a0',pear:'#d5b967',mandarin:'#eda03f'};
/** Borrow the original rig. No clone, second poser, light, camera, physics or save writer. */
export function createProduceSession({player,model,poser,zoneRoot,nodeId,kind,produceView=null,reduced=false}){
 const n=PRODUCE_BY_ID[nodeId];if(!n||!player||!model||!poser||!zoneRoot)throw Error('Produce actors missing');
 const root=new THREE.Group();root.name='produce.direct-care';zoneRoot.add(root);const previous={position:player.position.clone(),quaternion:player.quaternion.clone(),modelPosition:model.position.clone(),modelQuaternion:model.quaternion.clone()},materials=[],geometries=[],v=new THREE.Vector3(),end=new THREE.Vector3(),up=new THREE.Vector3(0,1,0),world=new THREE.Vector3();let disposed=false,basketFilled=false,pouring=false,grip=null,streamEnd=null;
 const mat=c=>{const m=new THREE.MeshStandardMaterial({color:c,roughness:.85});materials.push(m);return m};const clay=mat('#80aaa0'),bronze=mat('#ac8462'),blue=mat('#a6d5dc'),fruitMat=mat(FRUIT_COLORS[n.species]),green=mat('#6f9555');
 function mesh(g,m,p=[0,0,0],parent=root){geometries.push(g);const o=new THREE.Mesh(g,m);o.position.set(...p);parent.add(o);o.castShadow=true;return o;}
 const can=new THREE.Group();can.name='produce.watering-can';root.add(can);mesh(new THREE.CylinderGeometry(.16,.14,.23,12),clay,[0,-.21,.12],can);const handle=mesh(new THREE.TorusGeometry(.10,.022,6,12),bronze,[0,-.10,0],can);handle.rotation.y=Math.PI/2;const spout=mesh(new THREE.CylinderGeometry(.025,.042,.3,8),clay,[0,-.15,.33],can);spout.rotation.x=Math.PI/2-.25;const nozzle=new THREE.Object3D();nozzle.position.set(0,-.113,.475);can.add(nozzle);
 const stream=mesh(new THREE.CylinderGeometry(.011,.015,1,6),blue);stream.name='produce.water-stream';stream.castShadow=false;
 const basket=new THREE.Group();basket.name='produce.basket';root.add(basket);const bowl=mesh(new THREE.CylinderGeometry(.24,.17,.22,12,1,true),bronze,[0,.11,0],basket);bowl.material.side=THREE.DoubleSide;mesh(new THREE.CylinderGeometry(.17,.17,.035,12),bronze,[0,.016,0],basket);const rim=mesh(new THREE.TorusGeometry(.24,.022,5,12),bronze,[0,.22,0],basket);rim.rotation.x=Math.PI/2;
 const fruitGeos=produceGeometries();Object.values(fruitGeos).forEach(g=>geometries.push(g));const shape=n.species==='strawberry'?fruitGeos.berry:fruitGeos.round,held=new THREE.Mesh(shape,fruitMat);held.scale.set(.12,n.species==='pear'?.16:.12,.12);held.name='produce.held-fruit';root.add(held);const cap=mesh(new THREE.ConeGeometry(.055,.04,5),green,[0,n.species==='strawberry'?.105:.13,0],held);cap.scale.setScalar(1/ .12); // child coordinates below are in normalized parent space
 cap.position.set(0,1,0);cap.scale.set(.3,.3,.3);
 const deposited=[0,1].map(i=>{const o=new THREE.Mesh(shape,fruitMat);o.scale.set(.09,.10,.09);o.position.set(i? .095:-.08,.20,0);basket.add(o);return o});
 const targetWorld=zoneRoot.localToWorld(new THREE.Vector3(n.approach.x,.05,n.approach.z)),target=player.parent.worldToLocal(targetWorld.clone()),zoneQ=zoneRoot.getWorldQuaternion(new THREE.Quaternion()),parentQ=player.parent.getWorldQuaternion(new THREE.Quaternion()).invert(),targetQ=parentQ.multiply(zoneQ).multiply(new THREE.Quaternion().setFromAxisAngle(up,n.approach.yaw));
 const worldLocal=p=>zoneRoot.worldToLocal(p);
 function update(s){if(disposed)return;const t=s.elapsed??0;player.position.lerpVectors(previous.position,target,smooth(t/.4));player.quaternion.slerpQuaternions(previous.quaternion,targetQ,smooth(t/.4));model.position.set(0,0,0);model.quaternion.identity();const pick=kind==='harvest',amount=pick?t<=.9?smooth((t-.4)/.5):1-smooth((t-.9)/.7):smooth((t-.4)/.4);poser.setPose(pick?harvestPose(n):'water',amount,0);model.position.y=-Math.max(0,poser.getState().bodyBounds.min[1]);player.updateWorldMatrix(true,true);const hand=model.localToWorld(v.fromArray(poser.getAnchors().rightHand).clone());
  grip=hand.toArray();can.visible=!pick&&t>=.4&&s.phase!=='done'&&s.phase!=='failed';can.position.copy(worldLocal(hand.clone()));can.quaternion.copy(zoneRoot.getWorldQuaternion(new THREE.Quaternion()).invert().multiply(player.getWorldQuaternion(new THREE.Quaternion())));pouring=can.visible&&t>=.8&&!s.committed;stream.visible=pouring;if(pouring){can.updateWorldMatrix(true,true);const start=worldLocal(nozzle.getWorldPosition(world).clone());end.set(n.x+.25,.15,n.z+(n.z<0?.45:-.45));streamEnd=end.toArray();stream.position.copy(start).add(end).multiplyScalar(.5);const delta=end.clone().sub(start);stream.scale.set(1,delta.length(),1);stream.quaternion.setFromUnitVectors(up,delta.normalize());}
  basket.visible=pick;const basketWorld=player.localToWorld(new THREE.Vector3(.545,.04,.025));basket.position.copy(worldLocal(basketWorld));basket.quaternion.copy(can.quaternion);held.visible=pick&&s.committed&&t<1.6;held.position.copy(worldLocal(hand.clone()));basketFilled=pick&&s.committed&&t>=1.6;deposited.forEach(o=>o.visible=basketFilled);produceView?.setCare(nodeId,kind==='water'?Math.min(1,t/2):0);
 }
 update({elapsed:0,committed:false,phase:'acting'});return {root,update,settle(){stream.visible=false;pouring=false;produceView?.setCare(null,0)},snapshot:()=>({pouring,grip,streamEnd,basketFilled}),dispose(){if(disposed)return;disposed=true;produceView?.setCare(null,0);root.removeFromParent();player.position.copy(previous.position);player.quaternion.copy(previous.quaternion);model.position.copy(previous.modelPosition);model.quaternion.copy(previous.modelQuaternion);poser.reset();new Set(geometries).forEach(g=>g.dispose());materials.forEach(m=>m.dispose());}};
}
